          border border-white/20 flex flex-col overflow-hidden mb-5 
          transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)] 
          animate-in fade-in slide-in-from-bottom-8 pointer-events-auto
        `}>
          {/* Header */}
          <div className="bg-[#1e293b] p-5 flex items-center justify-between relative overflow-hidden group/header">
            <div className="absolute inset-0 bg-gradient-to-r from-navy to-navy/80 opacity-90"></div>
            <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/10 rounded-full blur-2xl -translate-y-1/2 translate-x-1/2"></div>

            <div className="relative z-10 flex items-center gap-3">
              <div className="w-11 h-11 bg-gradient-to-tr from-orange-400 to-orange-600 rounded-2xl flex items-center justify-center text-white shadow-lg transform group-hover/header:rotate-6 transition-transform">
                <Bot size={24} />
              </div>
              <div>
                <h3 className="text-white font-black text-sm tracking-tight leading-none mb-1">Gov-Smart AI</h3>
                <div className="flex items-center gap-1.5">
                  <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                  <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Assistant Online</span>
                </div>
              </div>
            </div>

            <div className="relative z-10 flex items-center gap-1">
              <button 
                onClick={() => setShowSettings(!showSettings)} 
