              {/* Chat Body */}
              <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-[#f8fafc]/50 relative custom-scrollbar">
                {showSettings && (
                  <div className="sticky top-0 z-20 bg-white/80 backdrop-blur-md p-4 rounded-3xl border border-gray-100 shadow-xl mb-6 animate-in zoom-in-95 duration-200">
