  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपका सरकारी योजना सहायक हूँ। आप मुझसे कुछ भी पूछ सकते हैं।' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुमचा सरकारी योजना सहाय्यक आहे. मला काहीही विचारा.' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்கள் அரசுத் திட்ட உதவியாளர். என்னிடம் எதையும் கேளுங்கள்.' },
];

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const ChatWidget: React.FC = () => {
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentTtsTextRef = useRef<string | null>(null);

  useEffect(() => {
    if (scrollRef.current && isOpen && !isMinimized) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isLoading, isOpen, isMinimized]);

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const handleTTS = async (text: string) => {
    if (isPlaying && currentTtsTextRef.current === text) {
      audioSourceRef.current?.stop();
      setIsPlaying(false);
      return;
    }

    audioSourceRef.current?.stop();
    setIsPlaying(true);
    currentTtsTextRef.current = text;

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
          if (currentTtsTextRef.current === text) setIsPlaying(false);
        };
        audioSourceRef.current = source;
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const schemeMatch = location.pathname.match(/\/scheme\/([^/]+)/);
    const contextScheme = schemeMatch ? MOCK_SCHEMES.find(s => s.id === schemeMatch[1]) : null;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the Gov-Smart AI Assistant.
          Current Context: ${contextScheme ? `The user is looking at the scheme: "${contextScheme.title}".` : 'General browsing.'}
          Knowledge Base (Popular Schemes): ${JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description })))}.
          User Preferred Language: ${selectedLang.name}.
          Rules:
          1. Provide accurate information based on the knowledge base.
          2. If asked about eligibility, refer to common Indian demographics.
          3. Be concise, friendly, and professional.
          4. If the language is not English, respond entirely in ${selectedLang.name}.`
        }
      });

      const aiResponse = response.text || "I'm sorry, I encountered an issue processing your request.";
      setMessages(prev => [...prev, { role: 'ai', text: aiResponse }]);
    } catch (error) {
      console.error("AI Generation Error:", error);
      setMessages(prev => [...prev, { role: 'ai', text: "The service is currently overwhelmed. Please try again in a moment." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-4 right-4 sm:bottom-6 sm:right-6 z-[10000] flex flex-col items-end pointer-events-none">
      {isOpen && (
        <div className={`
          w-[calc(100vw-32px)] sm:w-[400px] 
          ${isMinimized ? 'h-[72px]' : 'h-[min(580px,calc(100vh-120px))]'}
          bg-white/95 backdrop-blur-2xl rounded-[2rem] shadow-[0_20px_60px_-15px_rgba(15,23,42,0.3)] 
          border border-white/40 flex flex-col overflow-hidden mb-4 
          transition-all duration-400 ease-[cubic-bezier(0.23,1,0.32,1)] 
          animate-in fade-in slide-in-from-bottom-4 pointer-events-auto
        `}>
          {/* Enhanced Header */}
          <div className="bg-[#1e293b] px-5 py-4 flex items-center justify-between relative overflow-hidden group/header shrink-0">
            <div className="absolute inset-0 bg-gradient-to-br from-[#1e293b] via-[#1e293b] to-[#334155] opacity-95"></div>

            <div className="relative z-10 flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-tr from-orange-400 to-orange-600 rounded-xl flex items-center justify-center text-white shadow-lg transform group-hover/header:scale-105 transition-transform duration-300">
                <Bot size={20} />
              </div>
              <div className="flex flex-col">
                <h3 className="text-white font-bold text-sm tracking-tight leading-tight">Assistant</h3>
                <div className="flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.6)]"></span>
                  <span className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">Active Now</span>
                </div>
              </div>
            </div>

            <div className="relative z-10 flex items-center gap-1">
              <button 
                onClick={() => setShowSettings(!showSettings)} 
                title="Change Language"
                className={`p-2 rounded-lg transition-all ${showSettings ? 'bg-white/10 text-orange-400' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
              >
                <Globe size={18} />
              </button>
              <button 
                onClick={() => setIsMinimized(!isMinimized)} 
                className="p-2 text-gray-400 hover:text-white hover:bg-white/5 rounded-lg transition-all"
              >
                {isMinimized ? <Maximize2 size={18} /> : <Minus size={18} />}
              </button>
              <button 
                onClick={() => setIsOpen(false)} 
                className="p-2 text-gray-400 hover:text-red-400 hover:bg-red-400/5 rounded-lg transition-all"
              >
                <X size={18} />
              </button>
            </div>
          </div>

          {!isMinimized && (
            <>
              {/* Responsive Chat Body */}
              <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-5 bg-[#f8fafc]/40 relative custom-scrollbar flex flex-col">
                {showSettings && (
                  <div className="sticky top-0 z-20 bg-white/90 backdrop-blur-md p-3 rounded-2xl border border-gray-100 shadow-lg mb-4 animate-in zoom-in-95 duration-300">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 px-1">Choose Language</p>
                    <div className="grid grid-cols-2 gap-2">
                      {LANGUAGES.map(lang => (
                        <button 
                          key={lang.code} 
                          onClick={() => { setSelectedLang(lang); setShowSettings(false); setMessages([{role:'ai', text: lang.greeting}]) }}
                          className={`
                            px-3 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-between
                            ${selectedLang.code === lang.code 
                              ? 'bg-[#1e293b] text-white shadow-md' 
                              : 'bg-white text-gray-500 hover:bg-gray-50 border border-gray-100'}
