                                ${isPlaying && currentTtsTextRef.current === msg.text 
                                  ? 'bg-orange-100 text-orange-600' 
                                  : 'bg-gray-100 text-gray-400 hover:text-[#1e293b]'}
                              `}
                            >
                              {isPlaying && currentTtsTextRef.current === msg.text ? <VolumeX size={12} /> : <Volume2 size={12} />}
                              {isPlaying && currentTtsTextRef.current === msg.text ? 'Stop' : 'Listen'}
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}

                  {isLoading && (
                    <div className="flex justify-start">
                      <div className="bg-white border border-gray-100 p-4 rounded-2xl rounded-tl-none flex items-center gap-3">
