                          <div className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                          <div className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce"></div>
                        </div>
                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Thinking</span>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Input Area */}
              <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-gray-50 flex items-center gap-2 shrink-0">
                <div className="relative flex-1 group">
                  <input 
                    type="text" 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask about schemes..."
                    className="
                      w-full pl-4 pr-10 py-3.5 bg-gray-50 border border-transparent rounded-xl 
                      text-sm font-semibold text-[#1e293b] focus:bg-white focus:border-orange-200 
                      focus:ring-2 focus:ring-orange-500/5 outline-none transition-all placeholder:text-gray-400
                    "
                  />
                  <button 
                    type="button" 
                    onClick={toggleListening} 
                    className={`
                      absolute right-1.5 top-1/2 -translate-y-1/2 w-8 h-8 rounded-lg flex items-center justify-center transition-all
                      ${isListening 
                        ? 'bg-red-500 text-white shadow-lg animate-pulse' 
                        : 'text-gray-400 hover:text-[#1e293b] hover:bg-gray-100'}
                    `}
                  >
                    {isListening ? <MicOff size={16} /> : <Mic size={16} />}
                  </button>
                </div>
                <button 
                  type="submit" 
                  disabled={!input.trim() || isLoading} 
                  className="
                    w-11 h-11 bg-[#1e293b] text-white rounded-xl flex items-center justify-center 
                    hover:bg-orange-primary disabled:opacity-20 transition-all shadow-md
                    active:scale-95
