          <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full border-2 border-white flex items-center justify-center animate-bounce shadow-sm">
            <span className="text-[9px] font-black">1</span>
          </div>
        )}
      </button>
    </div>
  );
};

