                  onClick={toggleListening} 
                  className={`
                    absolute right-1.5 top-1/2 -translate-y-1/2 w-9 h-9 rounded-xl flex items-center justify-center transition-all
                    ${isListening 
                      ? 'bg-red-500 text-white shadow-lg animate-pulse' 
