import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Bookmark, 
  ArrowRight, 
  Zap, 
  CheckCircle2, 
  User,
  Search,
  Settings,
  AlertCircle,
  Clock,
  ExternalLink,
  ChevronRight,
  ShieldCheck
} from 'lucide-react';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { MOCK_SCHEMES } from '../constants';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<any>(null);
  const [savedCount, setSavedCount] = useState(0);

  useEffect(() => {
    const checkAuth = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const user = JSON.parse(savedUser);

      try {
        const docRef = doc(db, "profiles", user.id);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          setProfile(docSnap.data());
        } else {
          setProfile({ first_name: user.username || 'User' });
        }
      } catch (err) {
        console.error("Dashboard profile fetch error:", err);
        setProfile({ first_name: user.username || 'User' });
      }

      const saved = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      setSavedCount(saved.length);

      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8fafc]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-navy border-t-orange-primary rounded-full animate-spin"></div>
          <p className="text-navy font-bold text-sm">Syncing your data...</p>
        </div>
      </div>
    );
  }

  const getMissingFields = () => {
    const fields = [
      { key: 'age', label: 'Age' },
      { key: 'state', label: 'State' },
      { key: 'occupation', label: 'Occupation' },
      { key: 'income', label: 'Annual Income' }
    ];
    return fields.filter(f => !profile?.[f.key] || profile?.[f.key] === '');
  };

  const missingFields = getMissingFields();
  const completion = Math.round(((4 - missingFields.length) / 4) * 100);

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-24">
      {/* Header Section */}
      <div className="bg-white border-b border-gray-100 pt-12 pb-8">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <div className="flex items-center gap-5">
              <div className="w-16 h-16 bg-navy rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-lg">
                {profile?.first_name?.[0] || 'U'}
              </div>
              <div>
                <h1 className="text-2xl font-black text-navy leading-tight">Welcome back, {profile?.first_name || 'Citizen'}!</h1>
                <p className="text-gray-500 text-sm font-medium flex items-center gap-1.5 mt-1">
                  <ShieldCheck size={14} className="text-green-500" />
                  Your cloud profile is verified and active
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button onClick={() => navigate('/settings')} className="flex items-center gap-2 px-5 py-2.5 rounded-xl border border-gray-200 text-gray-600 font-bold text-sm hover:bg-gray-50 transition-all">
                <Settings size={18} /> Edit Profile
              </button>
              <button onClick={() => navigate('/find-schemes')} className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-orange-primary text-white font-bold text-sm hover:bg-orange-600 transition-all shadow-lg shadow-orange-500/20">
                <Search size={18} /> New Search
              </button>
            </div>
          </div>

          {/* Profile Health Bar */}
          <div className="mt-10 p-5 bg-gray-50 rounded-2xl border border-gray-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex-1">
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs font-black text-navy uppercase tracking-widest">Profile Completion</span>
                <span className="text-xs font-bold text-orange-600">{completion}%</span>
              </div>
              <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                <div className="h-full bg-orange-primary transition-all duration-1000" style={{ width: `${completion}%` }}></div>
              </div>
            </div>
            {missingFields.length > 0 ? (
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2 text-red-500 text-xs font-bold">
                  <AlertCircle size={14} /> Missing: {missingFields.map(f => f.label).join(', ')}
                </div>
                <Link to="/settings" className="text-navy font-black text-xs underline underline-offset-4 hover:text-orange-primary">Fix Now</Link>
              </div>
            ) : (
              <div className="flex items-center gap-2 text-green-600 text-xs font-bold">
                <CheckCircle2 size={16} /> Fully Optimized for AI Matching
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

          {/* Main Feed */}
          <div className="lg:col-span-8 space-y-10">

            {/* Stats Summary */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              {[
                { label: 'AI Matches', value: '12', icon: <Zap size={20} />, color: 'text-orange-600', bg: 'bg-orange-50' },
                { label: 'Saved Schemes', value: savedCount, icon: <Bookmark size={20} />, color: 'text-blue-600', bg: 'bg-blue-50' },
                { label: 'Applied', value: '0', icon: <CheckCircle2 size={20} />, color: 'text-green-600', bg: 'bg-green-50' }
              ].map((stat, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4">
                  <div className={`w-12 h-12 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center`}>
                    {stat.icon}
                  </div>
                  <div>
                    <div className="text-2xl font-black text-navy tracking-tight">{stat.value}</div>
                    <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{stat.label}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* Smart Matches Section */}
            <div>
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-black text-navy flex items-center gap-2">
                  <Zap size={20} className="text-orange-500" /> Top AI Matches for You
                </h2>
                <Link to="/find-schemes" className="text-xs font-bold text-gray-400 hover:text-navy flex items-center gap-1">
                  View full list <ChevronRight size={14} />
                </Link>
              </div>

              <div className="space-y-4">
                {MOCK_SCHEMES.slice(0, 3).map((scheme) => (
                  <div 
                    key={scheme.id}
                    onClick={() => navigate(`/scheme/${scheme.id}`)}
                    className="bg-white p-6 rounded-3xl border border-gray-100 hover:border-orange-200 hover:shadow-xl transition-all cursor-pointer group flex flex-col sm:flex-row sm:items-center gap-6"
                  >
                    <div className="flex-1 space-y-3">
                      <div className="flex items-center gap-2">
                        <span className="px-2.5 py-1 bg-gray-50 border border-gray-100 text-[9px] font-black uppercase text-gray-500 rounded-lg">
                          {scheme.category}
