                        <div className="flex items-center gap-1 text-[9px] font-black text-green-600 uppercase">
                          98% MATCH
                        </div>
                      </div>
                      <h3 className="text-lg font-extrabold text-navy group-hover:text-orange-primary transition-colors leading-tight">
                        {scheme.title}
