import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Bookmark, ChevronLeft, ChevronRight, Search, Trash2, Clock, Zap, ArrowRight } from 'lucide-react';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

const SavedSchemes: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [savedSchemes, setSavedSchemes] = useState<Scheme[]>([]);

  useEffect(() => {
    const fetchSaved = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const savedIds = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      const filtered = MOCK_SCHEMES.filter(s => savedIds.includes(s.id));
      setSavedSchemes(filtered);
      setLoading(false);
    };

    fetchSaved();
  }, [navigate]);

  const removeScheme = (id: string) => {
    const current = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
    const updated = current.filter((sid: string) => sid !== id);
    localStorage.setItem('saved_schemes', JSON.stringify(updated));
    setSavedSchemes(prev => prev.filter(s => s.id !== id));
    window.dispatchEvent(new Event('storage'));
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8fafc]">
        <div className="w-12 h-12 border-4 border-navy/10 border-t-orange-primary rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-32">
      {/* Dynamic Sub-nav */}
      <div className="bg-white border-b sticky top-20 z-40 transition-all duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <Link to="/dashboard" className="inline-flex items-center gap-2 text-sm font-black text-gray-400 hover:text-navy transition-all group">
              <ChevronLeft size={20} className="group-hover:-translate-x-1 transition-transform" /> Back to Dashboard
            </Link>
            <div className="flex items-center gap-2 px-5 py-2 bg-blue-50 text-blue-700 rounded-full text-xs font-black border border-blue-100 uppercase tracking-widest">
              <Bookmark size={14} fill="currentColor" /> {savedSchemes.length} Programs Bookmarked
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16">
        <div className="mb-16 space-y-4">
          <h1 className="text-4xl sm:text-5xl font-black text-navy tracking-tight">Saved for Later</h1>
          <p className="text-lg text-gray-500 font-medium max-w-2xl leading-relaxed">
            Quickly access the schemes you've bookmarked. Review the eligibility rules and start your application whenever you're ready.
          </p>
        </div>

        {savedSchemes.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {savedSchemes.map((scheme, idx) => (
              <div 
                key={scheme.id} 
                className="bg-white rounded-[2.5rem] border border-gray-100 hover:border-orange-200 hover:shadow-2xl transition-all group flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500"
                style={{ animationDelay: `${idx * 100}ms` }}
              >
                <div className="p-8 sm:p-10 flex-grow space-y-6">
                  <div className="flex justify-between items-start">
                    <div className="flex flex-wrap gap-2">
                      <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black uppercase rounded-lg tracking-widest">{scheme.category}</span>
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 text-[10px] font-black uppercase rounded-lg tracking-widest">{scheme.level}</span>
                    </div>
                    <button 
                      onClick={() => removeScheme(scheme.id)}
                      className="text-gray-300 hover:text-red-500 transition-colors p-3 rounded-2xl hover:bg-red-50 active:scale-90"
                      title="Remove from saved"
                    >
                      <Trash2 size={20} />
                    </button>
                  </div>

                  <div className="space-y-4">
                    <h3 className="text-2xl font-black text-navy leading-tight group-hover:text-orange-primary transition-colors line-clamp-2">
                      {scheme.title}
                    </h3>
                    <p className="text-base text-gray-500 font-medium leading-relaxed line-clamp-3">
                      {scheme.description}
                    </p>
                  </div>

                  <div className="flex items-center gap-6 pt-2">
                    <div className="flex items-center gap-2 text-xs font-bold text-gray-400">
                      <Clock size={16} /> {scheme.updatedAt}
                    </div>
                    <div className="flex items-center gap-2 text-xs font-black text-orange-500 uppercase tracking-widest">
                      <Zap size={16} fill="currentColor" /> AI Score: 98%
                    </div>
                  </div>
                </div>

                <div className="p-8 sm:p-10 pt-4 border-t border-gray-50 bg-gray-50/50 rounded-b-[2.5rem]">
                  <button 
                    onClick={() => navigate(`/scheme/${scheme.id}`)}
                    className="w-full py-5 bg-white border-2 border-gray-100 text-navy font-black text-base rounded-2xl flex items-center justify-center gap-3 hover:bg-orange-primary hover:text-white hover:border-orange-primary transition-all shadow-sm hover:shadow-xl hover:shadow-orange-500/20 active:scale-95 group/btn"
                  >
                    View Full Details 
                    <ArrowRight size={20} className="group-hover/btn:translate-x-1 transition-transform" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
